int timeout = 0;
struct job_t *j = getjobpid(job_list, pid);
while (j->pid == pid && j->state == FG) {
if (++timeout > MAX_TIME) {
break;
}
}
}

void waitfg(pid_t pid) {
struct job_t *j = getjobpid(job_list, pid);
while (j->pid == pid && j->state == FG) {
sleep(1);
}
}

sigset_t oldmask;
void waitfg(pid_t pid) {
struct job_t *j = getjobpid(job_list, pid);
while (j->pid == pid && j->state == FG) {
